const storeCategories = {
    women: {
        title: "WOMEN COLLECTION",
        subcategories: [
            { id: "w-bags", name: "Handbags", image: "data:image/jpeg;base64," },
            { id: "w-necklaces", name: "Necklaces", image: "data:image/jpeg;base64," },
            { id: "w-bracelets", name: "Bracelets", image: "data:image/jpeg;base64," },
            { id: "w-rings", name: "Rings", image: "data:image/jpeg;base64," },
            { id: "w-earrings", name: "Earrings", image: "data:image/jpeg;base64," },
            { id: "w-watches", name: "Watches", image: "data:image/jpeg;base64," },
            { id: "w-sets", name: "Sets", image: "data:image/jpeg;base64," },
            { id: "w-compo", name: "Compo", image: "data:image/jpeg;base64," }
        ]
    },
    men: {
        title: "MEN COLLECTION",
        subcategories: [
            { id: "m-rings", name: "Rings", image: null },
            { id: "m-necklaces", name: "Necklaces", image: "data:image/jpeg;base64," },
            { id: "m-wallets", name: "Wallets", image: null },
            { id: "m-bracelets", name: "Bracelets", image: "data:image/jpeg;base64," },
            { id: "m-watches", name: "Watches", image: "data:image/jpeg;base64," }
        ]
    },
    couples: {
        title: "COUPLES COLLECTION",
        subcategories: [
            { id: "c-necklaces", name: "Couples Necklaces", image: "data:image/jpeg;base64," },
            { id: "c-bracelets", name: "Couples Bracelets", image: "data:image/jpeg;base64," }
        ]
    }
};

let cart = [];
let wishlist = JSON.parse(localStorage.getItem('athar_wishlist')) || [];
let accountData = JSON.parse(localStorage.getItem('athar_account')) || { name: '', phone: '', address: '' };

const heroSection = document.getElementById("hero-section");
const sectionHeading = document.getElementById("section-heading");
const subcatGrid = document.getElementById("subcategories-grid");
const productsGrid = document.getElementById("products-grid");
const breadcrumb = document.getElementById("breadcrumb");

function goHome() {
    setActiveTab("tab-home");
    if(heroSection) heroSection.style.display = "block";
    if(breadcrumb) breadcrumb.style.display = "none";
    if(subcatGrid) subcatGrid.style.display = "none";
    if(productsGrid) {
        productsGrid.style.display = "block";
        productsGrid.innerHTML = "";
    }
    if(sectionHeading) sectionHeading.innerText = "FEATURED COLLECTIONS";

    const categoriesMap = [
        { id: "w-bags", title: "Handbags" },
        { id: "w-necklaces", title: "Necklaces" },
        { id: "w-bracelets", title: "Bracelets" },
        { id: "w-rings", title: "Rings" },
        { id: "w-earrings", title: "Earrings" },
        { id: "w-sets", title: "Sets" },
        { id: "w-compo", title: "Compo" },
        { id: "m-watches", title: "Men Watches" },
        { id: "c-necklaces", title: "Couples Collection" }
    ];

    categoriesMap.forEach(cat => {
        const catProducts = products.filter(p => p.subcatId === cat.id);
        if (catProducts.length > 0) {
            let sectionHTML = `
                <div class="home-section-container" style="margin-bottom: 45px;">
                    <h3 class="home-section-title">${cat.title}</h3>
                    <div style="display: grid; grid-template-columns: repeat(auto-fill, minmax(220px, 1fr)); gap: 20px;">
            `;

            catProducts.forEach(product => {
                const isWishlisted = wishlist.some(item => item.id === product.id);
                const heartColor = isWishlisted ? '#ff3366' : '#aaa';
                let colorsHtml = product.colors && product.colors.length > 0 ? `<div style="margin: 6px 0;">` + product.colors.map(c => `<span style="display:inline-block; background:#222; color:#d4af37; border:1px solid #444; padding:2px 8px; border-radius:12px; font-size:11px; margin:2px;">${c}</span>`).join('') + `</div>` : '';

                sectionHTML += `
                    <div class="product-card" style="background:#1a1a1a; border:1px solid #333; border-radius:12px; padding:12px; text-align:center; position:relative;">
                        <button onclick="toggleWishlist(${product.id})" style="position:absolute; top:16px; left:16px; background:rgba(0,0,0,0.6); border:none; border-radius:50%; width:32px; height:32px; cursor:pointer; font-size:16px; color:${heartColor}; z-index:10;" title="المفضلة">❤️</button>
                        
                        <div class="square-img-box" onclick="openProductModal(${product.id})" style="cursor:pointer;">
                            <img src="${product.image}" alt="${product.name}">
                        </div>
                        <div>
                            <h4 onclick="openProductModal(${product.id})" style="color:#fff; margin:10px 0 5px; font-size:16px; cursor:pointer;">${product.name}</h4>
                            <div style="color:#f5c518; font-size:13px; margin:3px 0;">⭐⭐⭐⭐⭐</div>
                            ${colorsHtml}
                            <div style="color:#d4af37; font-weight:bold; font-size:16px; margin:8px 0;">${product.price} EGP</div>
                            <button onclick="addToCart(${product.id})" style="background:#d4af37; color:#000; border:none; padding:10px; width:100%; border-radius:8px; font-weight:bold; cursor:pointer;">ADD TO CART</button>
                        </div>
                    </div>
                `;
            });

            sectionHTML += `</div></div>`;
            productsGrid.innerHTML += sectionHTML;
        }
    });

    if(productsGrid.innerHTML === "") {
        productsGrid.innerHTML = `<p style="text-align:center; color:#888; padding: 40px 0;">أضف منتجاتك من لوحة التحكم لتظهر هنا فوراً! 🔥</p>`;
    }
}

function selectMainCategory(catKey) {
    setActiveTab(`tab-${catKey}`);
    const category = storeCategories[catKey];
    if(heroSection) heroSection.style.display = "none";
    if(breadcrumb) {
        breadcrumb.style.display = "block";
        breadcrumb.innerHTML = `<span onclick="goHome()" style="cursor:pointer;">Home</span> / ${category.title}`;
    }
    if(sectionHeading) sectionHeading.innerText = category.title;
    if(productsGrid) productsGrid.style.display = "grid";
    if(subcatGrid) {
        subcatGrid.style.display = "grid";
        subcatGrid.innerHTML = "";
        category.subcategories.forEach(sub => {
            let imgContent = sub.image ? `<img src="${sub.image}" alt="${sub.name}">` : `<div class="coming-soon-box">Coming Soon 🔥</div>`;
            subcatGrid.innerHTML += `
                <div class="subcat-card" onclick="selectSubcategory('${catKey}', '${sub.id}', '${sub.name}')" style="cursor:pointer;">
                    <div class="square-img-box">${imgContent}</div>
                    <div class="subcat-title" style="margin-top:8px; font-weight:bold; color:#d4af37; text-align:center;">${sub.name}</div>
                </div>
            `;
        });
    }
    productsGrid.innerHTML = "";
}

function selectSubcategory(catKey, subId, subName) {
    const category = storeCategories[catKey];
    if(breadcrumb) breadcrumb.innerHTML = `<span onclick="goHome()" style="cursor:pointer;">Home</span> / <span onclick="selectMainCategory('${catKey}')" style="cursor:pointer;">${category.title}</span> / ${subName}`;
    if(sectionHeading) sectionHeading.innerText = subName;
    if(subcatGrid) subcatGrid.style.display = "none";
    if(productsGrid) productsGrid.style.display = "grid";
    const filteredProducts = products.filter(p => p.subcatId === subId);
    renderProductsGrid(filteredProducts);
}

function renderProductsGrid(list) {
    if(!productsGrid) return;
    productsGrid.innerHTML = "";
    if (list.length === 0) {
        productsGrid.innerHTML = `<p style="grid-column: 1/-1; text-align:center; color:#888; padding: 40px 0;">Items coming soon! Stay tuned 🔥</p>`;
        return;
    }
    list.forEach(product => {
        const isWishlisted = wishlist.some(item => item.id === product.id);
        const heartColor = isWishlisted ? '#ff3366' : '#aaa';
        let colorsHtml = product.colors && product.colors.length > 0 ? `<div style="margin: 6px 0;">` + product.colors.map(c => `<span style="display:inline-block; background:#222; color:#d4af37; border:1px solid #444; padding:2px 8px; border-radius:12px; font-size:11px; margin:2px;">${c}</span>`).join('') + `</div>` : '';

        productsGrid.innerHTML += `
            <div class="product-card" style="background:#1a1a1a; border:1px solid #333; border-radius:12px; padding:12px; text-align:center; position:relative;">
                <button onclick="toggleWishlist(${product.id})" style="position:absolute; top:16px; left:16px; background:rgba(0,0,0,0.6); border:none; border-radius:50%; width:32px; height:32px; cursor:pointer; font-size:16px; color:${heartColor}; z-index:10;" title="المفضلة">❤️</button>
                
                <div class="square-img-box" onclick="openProductModal(${product.id})" style="cursor:pointer;">
                    <img src="${product.image}" alt="${product.name}">
                </div>
                <div>
                    <h4 onclick="openProductModal(${product.id})" style="color:#fff; margin:10px 0 5px; font-size:16px; cursor:pointer;">${product.name}</h4>
                    <div style="color:#f5c518; font-size:13px; margin:3px 0;">⭐⭐⭐⭐⭐</div>
                    ${colorsHtml}
                    <div style="color:#d4af37; font-weight:bold; font-size:16px; margin:8px 0;">${product.price} EGP</div>
                    <button onclick="addToCart(${product.id})" style="background:#d4af37; color:#000; border:none; padding:10px; width:100%; border-radius:8px; font-weight:bold; cursor:pointer;">ADD TO CART</button>
                </div>
            </div>
        `;
    });
}

function setActiveTab(tabId) {
    document.querySelectorAll(".cat-tab").forEach(btn => btn.classList.remove("active"));
    const tab = document.getElementById(tabId);
    if(tab) tab.classList.add("active");
}

function openProductModal(id) {
    const product = products.find(p => p.id === id);
    if(!product) return;
    document.getElementById('modal-prod-img').src = product.image;
    document.getElementById('modal-prod-name').innerText = product.name;
    document.getElementById('modal-prod-price').innerText = product.price + ' EGP';
    document.getElementById('rating-msg').innerText = "اضغط على النجوم للتقييم!";
    
    let colorsHtml = product.colors && product.colors.length > 0 ? product.colors.map(c => `<span style="display:inline-block; background:#222; color:#d4af37; border:1px solid #444; padding:3px 10px; border-radius:12px; font-size:12px; margin:2px;">${c}</span>`).join('') : '';
    document.getElementById('modal-prod-colors').innerHTML = colorsHtml;

    document.getElementById('modal-add-btn').onclick = function() {
        addToCart(product.id);
        closeProductModal();
    };
    document.getElementById('product-modal').style.display = 'flex';
}

function closeProductModal(e) {
    if(!e || e.target.id === 'product-modal' || e.target.classList.contains('close-modal')) {
        document.getElementById('product-modal').style.display = 'none';
    }
}

function rateProduct(stars) {
    document.getElementById('rating-msg').innerText = `تم تقييم المنتج بـ ${stars} نجوم بنجاح! ⭐ شكراً لك`;
    for(let i=1; i<=5; i++) {
        const s = document.getElementById(`star-${i}`);
        if(i <= stars) s.style.color = "#f5c518";
        else s.style.color = "#444";
    }
}

function toggleWishlist(id) {
    const product = products.find(p => p.id === id);
    if(!product) return;
    const idx = wishlist.findIndex(item => item.id === id);
    if(idx > -1) wishlist.splice(idx, 1);
    else wishlist.push(product);
    
    localStorage.setItem('athar_wishlist', JSON.stringify(wishlist));
    updateWishlistUI();
    if(document.getElementById('tab-home').classList.contains('active')) goHome();
}

function updateWishlistUI() {
    document.getElementById('wishlist-count').innerText = wishlist.length;
    const container = document.getElementById('wishlist-items-container');
    if(!container) return;
    container.innerHTML = '';
    if(wishlist.length === 0) {
        container.innerHTML = '<p style="color:#888; text-align:center;">قائمة المفضلة فارغة حالياً.</p>';
        return;
    }
    wishlist.forEach((item) => {
        container.innerHTML += `
            <div style="display:flex; justify-content:space-between; align-items:center; background:#252525; padding:8px; border-radius:6px; margin-bottom:8px;">
                <div style="display:flex; align-items:center; gap:10px;">
                    <img src="${item.image}" style="width:40px; height:40px; object-fit:cover; border-radius:4px;">
                    <div>
                        <h4 style="margin:0; font-size:14px; color:#fff;">${item.name}</h4>
                        <span style="color:#d4af37; font-size:12px;">${item.price} EGP</span>
                    </div>
                </div>
                <button onclick="toggleWishlist(${item.id})" style="background:#dc3545; color:#fff; border:none; padding:4px 8px; border-radius:4px; font-size:11px; cursor:pointer;">حذف</button>
            </div>
        `;
    });
}

function toggleWishlistModal() {
    const modal = document.getElementById('wishlist-modal');
    modal.style.display = modal.style.display === 'flex' ? 'none' : 'flex';
    updateWishlistUI();
}

function toggleAccountModal() {
    const modal = document.getElementById('account-modal');
    modal.style.display = modal.style.display === 'flex' ? 'none' : 'flex';
}

function saveAccountData() {
    const name = document.getElementById('acc-name').value.trim();
    const phone = document.getElementById('acc-phone').value.trim();
    const address = document.getElementById('acc-address').value.trim();

    if(!name || !phone || !address) {
        alert('من فضلك املأ جميع بيانات الحساب.');
        return;
    }

    accountData = { name, phone, address };
    localStorage.setItem('athar_account', JSON.stringify(accountData));
    
    document.getElementById('cust-name').value = name;
    document.getElementById('cust-phone').value = phone;
    document.getElementById('cust-address').value = address;

    alert('تم حفظ بيانات الحساب بنجاح! ✅');
    toggleAccountModal();
}

function loadAccountDataToCheckout() {
    if(accountData.name) {
        document.getElementById('cust-name').value = accountData.name;
        document.getElementById('cust-phone').value = accountData.phone;
        document.getElementById('cust-address').value = accountData.address;
    }
    document.getElementById('acc-name').value = accountData.name || '';
    document.getElementById('acc-phone').value = accountData.phone || '';
    document.getElementById('acc-address').value = accountData.address || '';
    document.getElementById('wishlist-count').innerText = wishlist.length;
}

function addToCart(id) {
    const item = products.find(p => p.id === id);
    if(item) {
        cart.push(item);
        updateCartUI();
        toggleCart();
    }
}

function removeFromCart(index) {
    cart.splice(index, 1);
    updateCartUI();
}

function updateCartUI() {
    const countEl = document.getElementById("cart-count");
    if(countEl) countEl.innerText = cart.length;
    const cartItemsContainer = document.getElementById("cart-items");
    const cartTotalEl = document.getElementById("cart-total");
    if(!cartItemsContainer || !cartTotalEl) return;

    cartItemsContainer.innerHTML = "";
    let total = 0;
    cart.forEach((item, index) => {
        total += item.price;
        cartItemsContainer.innerHTML += `
            <div class="cart-item">
                <div class="cart-item-info">
                    <h4>${item.name}</h4>
                    <span>${item.price} EGP</span>
                </div>
                <button class="remove-btn" onclick="removeFromCart(${index})">Remove</button>
            </div>
        `;
    });
    cartTotalEl.innerText = total;
}

function toggleCart() {
    const sidebar = document.getElementById("cart-sidebar");
    const overlay = document.getElementById("cart-overlay");
    if(sidebar) sidebar.classList.toggle("active");
    if(overlay) overlay.classList.toggle("active");
    if(sidebar.classList.contains('active')) {
        loadAccountDataToCheckout();
    }
}

function checkoutWhatsApp() {
    if (cart.length === 0) {
        alert("Your cart is empty!");
        return;
    }
    const name = document.getElementById("cust-name").value.trim();
    const phone = document.getElementById("cust-phone").value.trim();
    const address = document.getElementById("cust-address").value.trim();

    if (!name || !phone || !address) {
        alert("Please fill in all shipping details before ordering.");
        return;
    }

    const phoneNumber = "201111506902";
    let message = `New Order from ATHAR Store:\n\n`;
    message += `Customer Name: ${name}\n`;
    message += `Phone Number: ${phone}\n`;
    message += `Address: ${address}\n\n`;
    message += `Items Ordered:\n`;

    let total = 0;
    cart.forEach(item => {
        message += `• ${item.name} - ${item.price} EGP\n`;
        total += item.price;
    });

    let advance = total * 0.25;
    message += `\nTotal Amount: ${total} EGP`;
    message += `\nRequired Advance (25%): ${advance} EGP (via InstaPay/Cash to 01111506902)`;
    message += `\nRemaining Upon Delivery: ${total - advance} EGP`;

    window.open(`https://wa.me/${phoneNumber}?text=${encodeURIComponent(message)}`, "_blank");
}

loadAccountDataToCheckout();
goHome();
